css:
.finclusion-sim-container {
    padding: 28px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: 'Courier New', 'SF Mono', 'Consolas', monospace;
    color: #c9d1d9;
}
.finclusion-sim-header {
    border-left: 4px solid #00ff88;
    padding: 24px 32px;
    margin-bottom: 28px;
    background: linear-gradient(135deg, rgba(0,255,136,0.06) 0%, rgba(0,191,255,0.04) 100%);
    border-radius: 0 12px 12px 0;
}
.finclusion-sim-header-tag {
    font-size: 0.65rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: #00bfff;
    margin-bottom: 8px;
    opacity: 0.8;
}
.finclusion-sim-header h1 {
    color: #00ff88;
    font-size: 1.6rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0 0 6px 0;
    font-weight: 700;
}
.finclusion-sim-subtitle {
    color: #6b7f99;
    font-size: 0.85rem;
    margin: 0;
    letter-spacing: 0.04em;
}
.finclusion-sim-period-counter {
    text-align: center;
    font-size: 1rem;
    color: #6b7f99;
    margin-bottom: 24px;
    padding: 10px;
    background: rgba(0,255,136,0.03);
    border: 1px solid #1a2744;
    border-radius: 8px;
}
.finclusion-sim-period-counter span {
    margin: 0 4px;
}
.finclusion-sim-period-counter #currentDay {
    color: #00ff88;
    font-weight: 700;
    font-size: 1.3rem;
}
.finclusion-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
    margin-bottom: 28px;
}
.finclusion-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 10px;
    padding: 20px 16px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, transform 0.15s ease;
}
.finclusion-sim-kpi-card:hover {
    border-color: #2a3f5f;
    transform: translateY(-2px);
}
.finclusion-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
}
.finclusion-sim-kpi-cash::before {
    background: linear-gradient(90deg, #00ff88, #00cc6a);
}
.finclusion-sim-kpi-portfolio::before {
    background: linear-gradient(90deg, #00bfff, #0088cc);
}
.finclusion-sim-kpi-default::before {
    background: linear-gradient(90deg, #ff6b35, #ff4444);
}
.finclusion-sim-kpi-clients::before {
    background: linear-gradient(90deg, #a78bfa, #7c3aed);
}
.finclusion-sim-kpi-social::before {
    background: linear-gradient(90deg, #fbbf24, #f59e0b);
}
.finclusion-sim-kpi-reg::before {
    background: linear-gradient(90deg, #34d399, #10b981);
}
.finclusion-sim-kpi-label {
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #6b7f99;
    margin-bottom: 10px;
}
.finclusion-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #e0e6f0;
}
.finclusion-sim-kpi-cash .finclusion-sim-kpi-value { color: #00ff88; }
.finclusion-sim-kpi-portfolio .finclusion-sim-kpi-value { color: #00bfff; }
.finclusion-sim-kpi-default .finclusion-sim-kpi-value { color: #ff6b35; }
.finclusion-sim-kpi-clients .finclusion-sim-kpi-value { color: #a78bfa; }
.finclusion-sim-kpi-social .finclusion-sim-kpi-value { color: #fbbf24; }
.finclusion-sim-kpi-reg .finclusion-sim-kpi-value { color: #34d399; font-size: 1.2rem; }
.finclusion-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 10px;
    padding: 0;
    margin-bottom: 28px;
    overflow: hidden;
    position: relative;
}
.finclusion-sim-briefing-bar {
    height: 3px;
    background: linear-gradient(90deg, #00bfff, #00ff88, #fbbf24);
}
.finclusion-sim-briefing-header {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    color: #00bfff;
    padding: 16px 24px 0 24px;
    font-weight: 700;
}
.finclusion-sim-briefing-body {
    padding: 12px 24px 20px 24px;
    font-size: 0.85rem;
    line-height: 1.65;
    color: #a0aec0;
}
.finclusion-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 10px;
    padding: 24px;
    margin-bottom: 28px;
}
.finclusion-sim-controls h3 {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #00ff88;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #1a2744;
}
.finclusion-sim-input-group {
    margin-bottom: 18px;
}
.finclusion-sim-input-group label {
    display: block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #8b9dc3;
    margin-bottom: 8px;
}
.finclusion-sim-input-group select {
    width: 100%;
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 6px;
    padding: 10px 14px;
    font-family: inherit;
    font-size: 0.82rem;
    transition: border-color 0.2s ease;
    -webkit-appearance: none;
    appearance: none;
}
.finclusion-sim-input-group select:focus {
    border-color: #00bfff;
    outline: none;
    box-shadow: 0 0 0 2px rgba(0,191,255,0.15);
}
.finclusion-sim-input-group input[type="range"] {
    width: 100%;
    -webkit-appearance: none;
    appearance: none;
    height: 6px;
    background: #1a2744;
    border-radius: 3px;
    outline: none;
}
.finclusion-sim-input-group input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: #00ff88;
    cursor: pointer;
    box-shadow: 0 0 8px rgba(0,255,136,0.4);
}
.finclusion-sim-input-group input[type="range"]::-moz-range-thumb {
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: #00ff88;
    cursor: pointer;
    border: none;
    box-shadow: 0 0 8px rgba(0,255,136,0.4);
}
.finclusion-sim-range-display {
    text-align: right;
    font-size: 1rem;
    font-weight: 700;
    color: #00ff88;
    margin-top: 4px;
}
.finclusion-sim-submit-btn {
    width: 100%;
    padding: 14px;
    background: linear-gradient(135deg, #00cc6a, #00ff88);
    color: #0a0f1e;
    font-family: inherit;
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    transition: opacity 0.2s ease, transform 0.15s ease;
    margin-top: 8px;
}
.finclusion-sim-submit-btn:hover {
    opacity: 0.9;
    transform: translateY(-1px);
}
.finclusion-sim-undo-btn {
    width: 100%;
    padding: 10px;
    background: transparent;
    color: #6b7f99;
    font-family: inherit;
    font-size: 0.75rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    cursor: pointer;
    margin-top: 8px;
    transition: border-color 0.2s ease, color 0.2s ease;
}
.finclusion-sim-undo-btn:hover {
    border-color: #ff6b35;
    color: #ff6b35;
}
.finclusion-sim-history {
    margin-bottom: 28px;
}
.finclusion-sim-container table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.78rem;
}
.finclusion-sim-container table thead th {
    background: #111827;
    color: #00bfff;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    padding: 10px 12px;
    border-bottom: 2px solid #1a2744;
    text-align: left;
}
.finclusion-sim-container table tbody td {
    padding: 8px 12px;
    border-bottom: 1px solid #151d2e;
    color: #a0aec0;
}
.finclusion-sim-container table tbody tr:hover td {
    background: rgba(0,255,136,0.03);
}
.finclusion-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 28px;
}
.finclusion-sim-chart-box {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 10px;
    padding: 20px;
    height: 280px;
    position: relative;
}
@media (max-width: 768px) {
    .finclusion-sim-container { padding: 16px; }
    .finclusion-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .finclusion-sim-charts { grid-template-columns: 1fr; }
    .finclusion-sim-kpi-value { font-size: 1.3rem; }
    .finclusion-sim-header h1 { font-size: 1.2rem; }
    .finclusion-sim-chart-box { height: 220px; }
}
@media (max-width: 480px) {
    .finclusion-sim-kpi-grid { grid-template-columns: 1fr; }
}

