        _updateBriefing(state) {
            if ((state.currentPeriod || 1) > 4) {
                var _p = ['round1Panel','round2Panel','round3Panel','round4Panel'];
                for (var _i = 0; _i < _p.length; _i++) { var _el = document.getElementById(_p[_i]); if (_el) _el.style.display = 'none'; }
                var _b = document.getElementById('briefingText');
                if (_b) _b.innerHTML = (this._getLang() === 'es') ? '<strong>Programa completado.</strong> Has finalizado las 4 rondas. Revisa tu puntuación y el resumen final.' : '<strong>Program complete.</strong> You have finished all 4 rounds. Review your score and final summary.';
                return;
            }
            var period = Math.min((state.currentPeriod || 1), 4);
            var idx = period - 1;
            var lang = this._getLang();
            var briefings = this.BRIEFINGS[lang] || this.BRIEFINGS['en'];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = briefings[idx];

