        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var compInput = document.getElementById('complianceBudgetInput');
                if (compInput) decisions.complianceBudget = parseInt(compInput.value);
                var legalInput = document.getElementById('legalApproachInput');
                if (legalInput) decisions.legalApproach = parseInt(legalInput.value);
                if (decisions.complianceBudget < 50000 || decisions.complianceBudget > 150000) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_warning'), 'warning');
                    return false;
                }
            } else if (period === 2) {
                var monInput = document.getElementById('monitoringLevelInput');
                if (monInput) decisions.monitoringLevel = parseInt(monInput.value);
                var insInput = document.getElementById('insuranceRateInput');
                if (insInput) decisions.insuranceRate = parseFloat(insInput.value);
            } else if (period === 3) {
                var socInput = document.getElementById('socialBudgetInput');
                if (socInput) decisions.socialBudget = parseInt(socInput.value);
                var focusInput = document.getElementById('programFocusInput');
                if (focusInput) decisions.programFocus = parseInt(focusInput.value);
                if (decisions.socialBudget > window.mySimulation.state.domainState.cash) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('insufficient_funds'), 'warning');
                    return false;
                }
            } else if (period === 4) {
                var growthInput = document.getElementById('growthTargetInput');
                if (growthInput) decisions.growthTarget = parseInt(growthInput.value);
                var techInput = document.getElementById('techBudgetInput');
                if (techInput) decisions.techBudget = parseInt(techInput.value);
                if (decisions.techBudget > window.mySimulation.state.domainState.cash) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('insufficient_funds'), 'warning');
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var investment = 0;
            var income = 0;
            var netResult = 0;

            if (period === 1) {
                investment = d.complianceBudget;
                var budgetFactor = (d.complianceBudget - 50000) / 100000 * 30;
                var legalFactor = d.legalApproach === 1 ? 5 : (d.legalApproach === 2 ? 20 : 35);
                ds.regulatoryScore = Math.min(100, Math.round(40 + budgetFactor + legalFactor));
                if (ds.regulatoryScore >= 85) {
                    ds.regulatoryStatus = 'approved';
                } else if (ds.regulatoryScore >= 65) {
                    ds.regulatoryStatus = 'conditional';
                } else {
                    ds.regulatoryStatus = 'review';
                }
                var interestIncome = Math.round(ds.portfolioValue * 0.15 / 2);
                var defaultLoss = Math.round(ds.portfolioValue * ds.defaultRate / 100);
                var adminCost = 40000;
                income = interestIncome - defaultLoss - adminCost;
                netResult = income - investment;
                ds.cash += netResult;

            } else if (period === 2) {
                var monitorCost = d.monitoringLevel === 1 ? 10000 : (d.monitoringLevel === 2 ? 25000 : 50000);
                var defaultReduction = d.monitoringLevel === 1 ? 0.3 : (d.monitoringLevel === 2 ? 1.2 : 2.5);
                var insuranceIncome = Math.round(ds.portfolioValue * d.insuranceRate / 100 / 2);
                ds.defaultRate = Math.max(1.0, ds.defaultRate - defaultReduction);
                if (d.insuranceRate >= 2.0) {
                    ds.defaultRate = Math.max(0.5, ds.defaultRate - 0.5);
                }
                var interestIncome2 = Math.round(ds.portfolioValue * 0.15 / 2);
                var defaultLoss2 = Math.round(ds.portfolioValue * ds.defaultRate / 100);
                var adminCost2 = 40000;
                investment = monitorCost;
                income = interestIncome2 + insuranceIncome - defaultLoss2 - adminCost2;
                netResult = income - investment;
                ds.cash += netResult;

            } else if (period === 3) {
                investment = d.socialBudget;
                var socialGain = Math.round((d.socialBudget / 100000) * 25);
                if (d.programFocus === 1) {
                    ds.defaultRate = Math.max(0.5, ds.defaultRate - 1.0);
                    socialGain += 5;
                } else if (d.programFocus === 2) {
                    var newBiz = Math.round((d.socialBudget / 10000) * 6);
                    ds.newBusinesses += newBiz;
                    ds.avgClientIncome += Math.round(newBiz * 4.2);
                    socialGain += 15;
                } else {
                    socialGain += 20;
                    ds.avgClientIncome += 80;
                }
                ds.socialScore = Math.min(100, ds.socialScore + socialGain);
                var interestIncome3 = Math.round(ds.portfolioValue * 0.15 / 2);
                var defaultLoss3 = Math.round(ds.portfolioValue * ds.defaultRate / 100);
                income = interestIncome3 - defaultLoss3 - 40000;
                netResult = income - investment;
                ds.cash += netResult;

            } else if (period === 4) {
                investment = d.techBudget;
                var expansionCost = Math.round(d.growthTarget * 12.5);
                investment += expansionCost;
                var regMultiplier = ds.regulatoryStatus === 'approved' ? 1.0 : (ds.regulatoryStatus === 'conditional' ? 0.6 : 0.25);
                var effectiveGrowth = Math.round(d.growthTarget * regMultiplier);
                ds.clientCount += effectiveGrowth;
                var newPortfolio = effectiveGrowth * 3000;
                ds.portfolioValue += newPortfolio;
                var techEfficiency = Math.min(0.4, d.techBudget / 1000000);
                var scaleAdminCost = Math.round(ds.clientCount * 200 * (1 - techEfficiency));
                var totalInterest = Math.round(ds.portfolioValue * 0.15);
                var totalDefaultLoss = Math.round(ds.portfolioValue * ds.defaultRate / 100);
                income = totalInterest - totalDefaultLoss - scaleAdminCost;
                netResult = income - investment;
                ds.cash += netResult;
                ds.socialScore = Math.min(100, ds.socialScore + Math.round(effectiveGrowth / 200));
            }

            ds.cashHistory.push(ds.cash);
            ds.portfolioHistory.push(ds.portfolioValue);
            ds.defaultHistory.push(ds.defaultRate);
            ds.socialHistory.push(ds.socialScore);
            var __sc = this._score(ds);
            ds.score = __sc;
            ds.performance = { overallScore: __sc, grade: (__sc>=80?'Excellent':(__sc>=55?'Good':(__sc>=35?'Adequate':'Needs Improvement'))) };


            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: period,
                investment: investment,
                income: income,
                netResult: netResult,
                defaultRate: ds.defaultRate,
                socialScore: ds.socialScore,
                cash: ds.cash,
                portfolioValue: ds.portfolioValue,
                clientCount: ds.clientCount,
                regulatoryStatus: ds.regulatoryStatus,
                overallScore: __sc,
                score: __sc
            };
        }

