            if (score >= 80) performance = __es ? 'Excelente' : 'Excellent';
            else if (score >= 55) performance = __es ? 'Buena' : 'Good';
            else if (score >= 35) performance = __es ? 'Adecuada' : 'Adequate';

            var insights = [];
            if (finalReg === 'approved') {
                insights.push(__es ? 'Aprobación regulatoria asegurada: estrategia de cumplimiento sólida.' : 'Regulatory approval secured — strong compliance strategy.');
            } else {
                insights.push(__es ? 'No se logró la aprobación regulatoria: considere invertir más en cumplimiento y estrategia legal.' : 'Regulatory approval was not achieved — consider investing more in compliance and legal strategy.');
            }
            if (finalDefault < 3) {
                insights.push(__es ? 'Tasa de mora bien controlada gracias a un monitoreo eficaz.' : 'Default rate well-controlled through effective monitoring.');
            }
            if (finalSocial > 60) {
                insights.push(__es ? 'Fuerte impacto social: se logró una inclusión financiera significativa.' : 'Strong social impact — meaningful financial inclusion achieved.');
