            if (finalCash < 200000) {
                insights.push(__es ? 'Las reservas de capital son bajas: equilibre la inversión con la sostenibilidad.' : 'Capital reserves are low — balance investment with sustainability.');
            }

            return {
                score: score,
                performance: performance,
                totalInvested: totalInvested,
                totalIncome: totalIncome,
                finalCash: finalCash,
                finalSocial: finalSocial,
                finalDefault: finalDefault,
                regulatoryOutcome: finalReg,
